/**
 * Prediction vs. Measurement Engine
 * 
 * Computes deterministic comparisons between theoretical calculations (predictions)
 * generated by authoritative scientific engines (PHEngineV2, ActiveMatterEngine,
 * ViscosityEngine, DensityEngine, LiquidNVREngine, ChelatorEngine) and real empirical
 * bench observations recorded in LIMS EvidenceRecords.
 * 
 * CRITICAL RULE:
 * Never overwrites predicted values with measured values, nor measured values with predictions.
 * Stores both separately and explicitly.
 */

import {
  PredictedMeasurement,
  ObservedMeasurement,
  PredictionVsMeasurementComparison,
} from './types';

/**
 * Compares a single predicted parameter against an observed empirical measurement
 */
export function comparePredictionVsMeasurement(
  predicted: PredictedMeasurement,
  observed: ObservedMeasurement
): PredictionVsMeasurementComparison {
  if (predicted.parameterKey !== observed.parameterKey) {
    throw new Error(
      `Mismatched parameter comparison: predicted '${predicted.parameterKey}' vs observed '${observed.parameterKey}'.`
    );
  }

  const absDiff = Math.abs(predicted.value - observed.value);
  const signedDev = observed.value - predicted.value;
  const relDiffPct =
    predicted.value !== 0
      ? Number(((absDiff / Math.abs(predicted.value)) * 100).toFixed(2))
      : 0;

  const hasUncertainty = observed.uncertainty !== undefined && observed.uncertainty > 0;
  const uncertaintyFormatted = hasUncertainty
    ? `±${observed.uncertainty} ${observed.unit}`
    : 'UNCERTAINTY_NOT_AVAILABLE';

  // Determine if within acceptable prediction tolerance range
  let isWithinPredictionTolerance = true;
  if (predicted.acceptableToleranceRange) {
    isWithinPredictionTolerance =
      observed.value >= predicted.acceptableToleranceRange.min &&
      observed.value <= predicted.acceptableToleranceRange.max;
  } else {
    // Default heuristic tolerance: within ±10% relative difference or ±0.3 pH units for pH
    if (predicted.parameterKey === 'ph') {
      isWithinPredictionTolerance = absDiff <= 0.35;
    } else {
      isWithinPredictionTolerance = relDiffPct <= 10.0;
    }
  }

  let deviationReasoning = `Observed ${observed.value} ${observed.unit} vs Predicted ${predicted.value} ${predicted.unit} (Delta: ${signedDev > 0 ? '+' : ''}${signedDev.toFixed(2)}, ${relDiffPct}% difference).`;
  if (!isWithinPredictionTolerance) {
    deviationReasoning += ` Exceeds expected prediction tolerance model limit.`;
  } else {
    deviationReasoning += ` Within accepted theoretical prediction tolerance.`;
  }

  return {
    parameterKey: predicted.parameterKey,
    parameterName: predicted.parameterName,
    unit: predicted.unit,
    predicted,
    observed,
    absoluteDifference: Number(absDiff.toFixed(3)),
    relativeDifferencePercent: relDiffPct,
    signedDeviation: Number(signedDev.toFixed(3)),
    hasUncertainty,
    uncertaintyFormatted,
    isWithinPredictionTolerance,
    deviationReasoning,
  };
}

/**
 * Batch compares multiple prediction vs measurement pairs
 */
export function comparePredictionVsMeasurementBatch(
  pairs: Array<{ predicted: PredictedMeasurement; observed: ObservedMeasurement }>
): PredictionVsMeasurementComparison[] {
  return pairs.map(pair => comparePredictionVsMeasurement(pair.predicted, pair.observed));
}
